-- Iran province/city directory and request table alignment.
-- Source: sajaddp/list-of-cities-in-Iran, official administrative divisions through 1404.
create table if not exists public.provinces (
  id uuid primary key default gen_random_uuid(),
  code integer not null unique,
  name text not null unique,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

alter table public.cities add column if not exists province_id uuid references public.provinces(id);
alter table public.cities drop constraint if exists cities_name_key;
create unique index if not exists cities_name_province_id_uidx on public.cities(name, province_id);
create index if not exists cities_province_id_idx on public.cities(province_id);

alter table public.projects add column if not exists category_id uuid references public.categories(id);
alter table public.projects add column if not exists target_worker_id uuid references public.profiles(id);

insert into public.provinces(code,name)
select x.code,x.name
from jsonb_to_recordset('[{"code":100,"name":"مرکزی"},{"code":101,"name":"گیلان"},{"code":102,"name":"مازندران"},{"code":103,"name":"آذربایجان شرقی"},{"code":104,"name":"آذربایجان غربی"},{"code":105,"name":"کرمانشاه"},{"code":106,"name":"خوزستان"},{"code":107,"name":"فارس"},{"code":108,"name":"کرمان"},{"code":109,"name":"خراسان رضوی"},{"code":110,"name":"اصفهان"},{"code":111,"name":"سیستان و بلوچستان"},{"code":112,"name":"کردستان"},{"code":113,"name":"همدان"},{"code":114,"name":"چهارمحال و بختیاری"},{"code":115,"name":"لرستان"},{"code":116,"name":"ایلام"},{"code":117,"name":"کهگیلویه و بویراحمد"},{"code":118,"name":"بوشهر"},{"code":119,"name":"زنجان"},{"code":120,"name":"سمنان"},{"code":121,"name":"یزد"},{"code":122,"name":"هرمزگان"},{"code":123,"name":"تهران"},{"code":124,"name":"اردبیل"},{"code":125,"name":"قم"},{"code":126,"name":"قزوین"},{"code":127,"name":"گلستان"},{"code":128,"name":"خراسان شمالی"},{"code":129,"name":"خراسان جنوبی"},{"code":130,"name":"البرز"}]'::jsonb) as x(code integer,name text)
on conflict(code) do update set name=excluded.name,is_active=true;

