},{"name":"دلند","province_code":127},{"name":"تاتار علیا","province_code":127},{"name":"مراوه","province_code":127},{"name":"گلیداغ","province_code":127},{"name":"گمیش تپه","province_code":127},{"name":"سیمین شهر","province_code":127},{"name":"ینقاق","province_code":127},{"name":"گالیکش","province_code":127},{"name":"صادق آباد","province_code":127},{"name":"پیش قلعه","province_code":128},{"name":"ماژان","province_code":129},{"name":"خوسف","province_code":129},{"name":"طبس","province_code":129},{"name":"عشق آباد","province_code":129},{"name":"دیهوک","province_code":129}]'::jsonb) as x(name text,province_code integer)
