-- Move references from the initial small city seed to the canonical province-linked rows.
with legacy as (
  select old.id old_id, fresh.id new_id
  from public.cities old
  join public.provinces p on p.name=old.province
  join public.cities fresh on fresh.name=old.name and fresh.province_id=p.id
  where old.province_id is null
)
update public.profiles pr set selected_city_id=l.new_id
from legacy l where pr.selected_city_id=l.old_id;

with legacy as (
  select old.id old_id, fresh.id new_id
  from public.cities old
  join public.provinces p on p.name=old.province
  join public.cities fresh on fresh.name=old.name and fresh.province_id=p.id
  where old.province_id is null
)
delete from public.worker_cities wc using legacy l
where wc.city_id=l.old_id and exists (
  select 1 from public.worker_cities w2 where w2.worker_id=wc.worker_id and w2.city_id=l.new_id
);

with legacy as (
  select old.id old_id, fresh.id new_id
  from public.cities old
  join public.provinces p on p.name=old.province
  join public.cities fresh on fresh.name=old.name and fresh.province_id=p.id
  where old.province_id is null
)
update public.worker_cities wc set city_id=l.new_id from legacy l where wc.city_id=l.old_id;

with legacy as (
  select old.id old_id, fresh.id new_id
  from public.cities old
  join public.provinces p on p.name=old.province
  join public.cities fresh on fresh.name=old.name and fresh.province_id=p.id
  where old.province_id is null
)
update public.projects pr set city_id=l.new_id from legacy l where pr.city_id=l.old_id;

delete from public.cities old
using public.provinces p, public.cities fresh
where old.province_id is null and p.name=old.province
  and fresh.name=old.name and fresh.province_id=p.id;

insert into public.categories(name,icon_key,is_active)
select 'سایر خدمات','more_horiz',true
where not exists(select 1 from public.categories where name='سایر خدمات');

alter table public.provinces enable row level security;
drop policy if exists "active provinces are public" on public.provinces;
create policy "active provinces are public"
on public.provinces for select to anon, authenticated using (is_active=true);

grant select on public.provinces to anon, authenticated;
grant select on public.cities to anon, authenticated;
